pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testRegression_property() public {
        address alice = address(0x123);
        vm.prank(alice);
        (bool success, ) = address(c).call(abi.encodeWithSignature("setOwner(address)", alice));
        if (success) {
            assertTrue(c.owner() == alice);
        } else {
            assertTrue(c.owner() == address(this));
        }
    }
}

